<script>
import { reactive, ref, watch, onMounted, onUnmounted, nextTick, inject } from 'vue'
import { useRouter } from 'vue-router'

export default {
  name: 'IndexPage',
  setup() {
    // 从 App.vue 注入全局 Toast
    const showToast = inject('showToast', () => {})
    const bgMode = inject('bgMode', ref('solid'))
    const router = useRouter()

    // ===== 能力图鉴数据 =====
    const skills = reactive([
      { icon: '🐛', name: '写Bug', width: 98, animated: false },
      { icon: '🔧', name: '修Bug', width: 30, animated: false },
      { icon: '🔍', name: '找Bug', width: 5, animated: false },
      { icon: '📋', name: 'Ctrl+C / Ctrl+V', width: 99, animated: false },
      { icon: '🎣', name: '摸鱼', width: 100, animated: false },
      { icon: '🤖', name: '调教AI', width: 95, animated: false }
    ])

    const skillTags = [
      'Vue.js', 'JavaScript', 'HTML & CSS', 'Python',
      'Node.js', 'Git & GitHub', 'C++', 'SQL', 'GDScript',
      'Blender', 'KubeJS',
    ]

    // ===== 兴趣爱好数据 =====
    const hobbies = [
      { icon: '💻', name: '写代码', desc: '80%摸鱼+20%代码' },
      { icon: '🎮', name: '打游戏', desc: '认真摸鱼时间' },
      { icon: '🎧', name: '听音乐', desc: '假装在听其实发呆' },
      { icon: '🛸', name: '调试虫洞', desc: '和Bug斗智斗勇' },
      { icon: '🧪', name: '折腾新技术', desc: '锟斤拷烫烫烫' },
      { icon: '☕', name: '喝咖啡', desc: '生命体征维持液' }
    ]

    // ===== 滚动渐入动画 =====
    let fadeObserver = null
    let skillObserver = null
    const musicContainer = ref(null)
    let musicIframe = null
    let musicTimer = null

    function loadMusic() {
      if (!musicContainer.value) return
      if (musicIframe) return // 已存在，不重复创建
      musicContainer.value.classList.remove('music-fade-out')
      musicIframe = document.createElement('iframe')
      musicIframe.frameBorder = '0'
      musicIframe.marginWidth = '0'
      musicIframe.marginHeight = '0'
      musicIframe.src = '//music.163.com/outchain/player?type=2&id=2026565329&auto=1&height=0'
      musicContainer.value.appendChild(musicIframe)
    }

    function stopMusic() {
      clearTimeout(musicTimer)
      if (!musicContainer.value) return
      musicContainer.value.classList.add('music-fade-out')
      musicTimer = setTimeout(() => {
        if (musicIframe) {
          musicIframe.remove()
          musicIframe = null
        }
      }, 600) // 与壁纸淡出同步
    }

    onMounted(() => {
      // 禁止页面滚动
      // 禁止页面滚动
      document.documentElement.style.overflow = 'hidden'
      document.body.style.overflow = 'hidden'

      // 时间问候
      const hour = new Date().getHours()
      let timeGreet
      if (hour < 6) timeGreet = '凌晨了还在写代码？早点休息 🌙'
      else if (hour < 9) timeGreet = '早上好！新的一天从写Bug开始 ☀️'
      else if (hour < 12) timeGreet = '上午好！摸鱼的好时光 🎣'
      else if (hour < 14) timeGreet = '中午好！该续杯咖啡了 ☕'
      else if (hour < 18) timeGreet = '下午好！Bug修完了吗？🐛'
      else if (hour < 22) timeGreet = '晚上好！高效时段到了 💻'
      else timeGreet = '夜深了，和Bug搏斗中… 🦉'

      setTimeout(() => {
        showToast(timeGreet)
      }, 300)

      // 渐入动画 Observer
      fadeObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible')
          }
        })
      }, {
        threshold: 0.15,
        rootMargin: '0px 0px -30px 0px'
      })

      const fadeElements = document.querySelectorAll('.homepage .fade-in')
      fadeElements.forEach(el => fadeObserver.observe(el))

      // 技能条动画 Observer（操作响应式数据，避免被 Vue 重渲染覆盖）
      skillObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const index = parseInt(entry.target.getAttribute('data-index'))
            if (!isNaN(index) && skills[index]) {
              skills[index].animated = true
            }
            skillObserver.unobserve(entry.target)
          }
        })
      }, { threshold: 0.3 })

      nextTick(() => {
        const skillBars = document.querySelectorAll('.homepage .skill-bar-fill')
        skillBars.forEach(bar => {
          skillObserver.observe(bar)
        })
      })
    })

    onUnmounted(() => {
      // 恢复页面滚动
      document.documentElement.style.overflow = ''
      document.body.style.overflow = ''

      if (fadeObserver) fadeObserver.disconnect()
      if (skillObserver) skillObserver.disconnect()
      clearTimeout(musicTimer)
    })

    // ===== 音乐随壁纸切换淡入淡出 =====
    watch(bgMode, (val) => {
      if (val === 'image') {
        loadMusic()
      } else {
        stopMusic()
      }
    }, { immediate: true })

    // ===== 返回 Coming Soon =====
    const goToComingSoon = () => {
      router.push('/')
    }

    return {
      skills,
      skillTags,
      hobbies,
      bgMode,
      musicContainer,
      goToComingSoon
    }
  }
}
</script>

